/**
 * The shape of the pinned SimulationCraft talent-identity artifact, and a
 * runtime validator for it.
 *
 * Generated by `scripts/authority/extract-simc-talents.mjs` from one exact
 * SimulationCraft commit and committed. Nothing here reaches the network.
 *
 * WHAT THIS DATA IS FOR, AND THE ONE THING IT MUST GET RIGHT
 *
 * The pinned `default[4]` Ambush condition asks three `talent.<name>` questions.
 * Answering them needs SimulationCraft's talent NAME mapped to the numeric ids a
 * Warcraft Logs `combatantinfo` carries.
 *
 * The load-bearing part is `alternativeEntries`. A WCL talent entry is
 * `{ id, rank, nodeId }`, and a CHOICE node offers several entries of which the
 * player picked one. Reading node presence as selection would resolve
 * `talent.improved_ambush` TRUE for a player who took Tight Spender at that same
 * node — which is exactly the real build this milestone was verified against. So
 * the siblings travel with the talent, and selection is decided by ENTRY id.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_TALENT_ARTIFACT_VERSION = 1;

export interface TalentArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface TalentArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly TalentArtifactSource[];
  readonly clientDataWowVersion: string;
  /** How the talent identities were established. Machine-extracted, unlike a token binding. */
  readonly talentDataMethod: string;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  /**
   * What the Warcraft Logs `combatantinfo` id space was observed to be, and for
   * which capture. Scoped deliberately: the equivalence is recorded for the
   * supported capture and parser version, not claimed for Warcraft Logs at large.
   */
  readonly wclIdSpaceNote: string;
  /** Why this dataset carries no fight-derived applicability gate. */
  readonly applicabilityNote: string;
}

/** Which talent tree a trait belongs to. */
export type TalentTree = "CLASS" | "SPECIALIZATION" | "HERO";

export const TALENT_TREES = ["CLASS", "SPECIALIZATION", "HERO"] as const satisfies readonly TalentTree[];

/**
 * Whether a node offers a single trait or a choice between several.
 *
 * `NORMAL` nodes carry no alternatives; `CHOICE` nodes must carry at least one.
 * The validator enforces both directions, because a CHOICE that lost its
 * siblings would silently become "node present means taken".
 */
export type TalentNodeType = "NORMAL" | "CHOICE";

export const TALENT_NODE_TYPES = ["NORMAL", "CHOICE"] as const satisfies readonly TalentNodeType[];

/** One sibling entry at a choice node. Selecting it means NOT selecting the talent. */
export interface TalentAlternativeEntry {
  readonly traitEntryId: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  readonly talentSpellId: number;
}

export interface TalentIdentity {
  /** The token as it appears after `talent.` in a SimulationCraft APL condition. */
  readonly simcName: string;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  readonly tree: TalentTree;
  /** `trait_data_t::id_node`. Matches a WCL entry's `nodeId`. */
  readonly traitNodeId: number;
  /** `trait_data_t::id_trait_node_entry`. Matches a WCL entry's `id`. THE identity. */
  readonly traitEntryId: number;
  /**
   * The spell the talent grants.
   *
   * Recorded for traceability only. It is NOT what a `combatantinfo` entry
   * carries, and it is NOT the proc buff a talent may trigger — the Blindside
   * talent (328085) and the Blindside proc buff (121153) are different facts.
   */
  readonly talentSpellId: number;
  readonly nodeType: TalentNodeType;
  /** Sibling entries at the same node. Non-empty exactly when `nodeType` is CHOICE. */
  readonly alternativeEntries: readonly TalentAlternativeEntry[];
  /** The pinned source line establishing SimulationCraft's binding for this name. */
  readonly binding: string;
}

export interface TalentArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: TalentArtifactProvenance;
  readonly talents: readonly TalentIdentity[];
}

/** Field names that must NOT appear on a talent: they are decided at read time. */
export const FORBIDDEN_DERIVED_TALENT_KEYS = ["taken", "selected", "isSelected", "rank"] as const;

export type TalentArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "MALFORMED_TALENTS"
  | "MALFORMED_TALENT"
  | "DUPLICATE_TALENT_NAME"
  | "DUPLICATE_TRAIT_ENTRY"
  | "CHOICE_NODE_WITHOUT_ALTERNATIVES"
  | "NORMAL_NODE_WITH_ALTERNATIVES";

export type TalentArtifactValidation =
  | { readonly ok: true; readonly artifact: TalentArtifact }
  | { readonly ok: false; readonly reason: TalentArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function positiveInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
}

function invalid(reason: TalentArtifactValidationReason, detail: string): TalentArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly TalentArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: TalentArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = positiveInt(raw, "byteLength");
    if (path === null || sha256 === null || byteLength === null) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

function validateProvenance(value: unknown): TalentArtifactProvenance | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const talentDataMethod = str(value, "talentDataMethod");
  const extractedOn = str(value, "extractedOn");
  const wclIdSpaceNote = str(value, "wclIdSpaceNote");
  const applicabilityNote = str(value, "applicabilityNote");
  const extractorVersion = positiveInt(value, "extractorVersion");
  const sources = validateSources(value["sources"]);

  if (
    repository === null ||
    commitSha === null ||
    clientDataWowVersion === null ||
    talentDataMethod === null ||
    extractedOn === null ||
    wclIdSpaceNote === null ||
    applicabilityNote === null ||
    extractorVersion === null ||
    sources === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;

  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    talentDataMethod,
    extractedOn,
    extractorVersion,
    wclIdSpaceNote,
    applicabilityNote,
  };
}

function validateAlternatives(value: unknown): readonly TalentAlternativeEntry[] | null {
  if (!Array.isArray(value)) return null;
  const alternatives: TalentAlternativeEntry[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const traitEntryId = positiveInt(raw, "traitEntryId");
    const nameEn = str(raw, "displayNameEn");
    const talentSpellId = positiveInt(raw, "talentSpellId");
    if (traitEntryId === null || nameEn === null || talentSpellId === null) return null;
    alternatives.push({ traitEntryId, displayNameEn: nameEn, talentSpellId });
  }
  return alternatives;
}

export function validateTalentArtifact(value: unknown): TalentArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  const artifactVersion = value["artifactVersion"];
  if (artifactVersion !== SUPPORTED_TALENT_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(artifactVersion)} is not ${SUPPORTED_TALENT_ARTIFACT_VERSION}`,
    );
  }

  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === null) {
    return invalid("MALFORMED_PROVENANCE", "provenance is incomplete or a hash is not a hash");
  }

  const talentsRaw = value["talents"];
  if (!Array.isArray(talentsRaw) || talentsRaw.length === 0) {
    return invalid("MALFORMED_TALENTS", "talents is not a non-empty array");
  }

  const talents: TalentIdentity[] = [];
  const seenNames = new Set<string>();
  const seenEntries = new Set<number>();

  for (let index = 0; index < talentsRaw.length; index += 1) {
    const raw = talentsRaw[index];
    if (!isRecord(raw)) return invalid("MALFORMED_TALENT", `talents[${index}] is not an object`);
    for (const forbidden of FORBIDDEN_DERIVED_TALENT_KEYS) {
      if (forbidden in raw) {
        return invalid(
          "MALFORMED_TALENT",
          `talents[${index}] stores '${forbidden}'; selection is decided per-fight, never baked into the dataset`,
        );
      }
    }

    const simcName = str(raw, "simcName");
    const nameEn = str(raw, "displayNameEn");
    const binding = str(raw, "binding");
    const traitNodeId = positiveInt(raw, "traitNodeId");
    const traitEntryId = positiveInt(raw, "traitEntryId");
    const talentSpellId = positiveInt(raw, "talentSpellId");
    const treeRaw = str(raw, "tree");
    const nodeTypeRaw = str(raw, "nodeType");
    const alternativeEntries = validateAlternatives(raw["alternativeEntries"]);

    if (
      simcName === null ||
      nameEn === null ||
      binding === null ||
      traitNodeId === null ||
      traitEntryId === null ||
      talentSpellId === null ||
      treeRaw === null ||
      nodeTypeRaw === null ||
      alternativeEntries === null
    ) {
      return invalid("MALFORMED_TALENT", `talents[${index}] is missing required fields`);
    }
    if (!(TALENT_TREES as readonly string[]).includes(treeRaw)) {
      return invalid("MALFORMED_TALENT", `talents[${index}] has unknown tree '${treeRaw}'`);
    }
    if (!(TALENT_NODE_TYPES as readonly string[]).includes(nodeTypeRaw)) {
      return invalid("MALFORMED_TALENT", `talents[${index}] has unknown nodeType '${nodeTypeRaw}'`);
    }

    const nodeType = nodeTypeRaw as TalentNodeType;
    // Both directions. A CHOICE that lost its siblings would silently degrade to
    // "node present means taken", which is the precise error this data exists to
    // make impossible.
    if (nodeType === "CHOICE" && alternativeEntries.length === 0) {
      return invalid("CHOICE_NODE_WITHOUT_ALTERNATIVES", simcName);
    }
    if (nodeType === "NORMAL" && alternativeEntries.length > 0) {
      return invalid("NORMAL_NODE_WITH_ALTERNATIVES", simcName);
    }
    // An entry id that is both the talent and one of its own alternatives would
    // make selection self-contradictory.
    if (alternativeEntries.some((entry) => entry.traitEntryId === traitEntryId)) {
      return invalid("DUPLICATE_TRAIT_ENTRY", `talents[${index}] lists its own entry as an alternative`);
    }

    if (seenNames.has(simcName)) return invalid("DUPLICATE_TALENT_NAME", simcName);
    if (seenEntries.has(traitEntryId)) return invalid("DUPLICATE_TRAIT_ENTRY", String(traitEntryId));
    seenNames.add(simcName);
    seenEntries.add(traitEntryId);

    talents.push({
      simcName,
      displayNameEn: nameEn,
      tree: treeRaw as TalentTree,
      traitNodeId,
      traitEntryId,
      talentSpellId,
      nodeType,
      alternativeEntries,
      binding,
    });
  }

  return { ok: true, artifact: { artifactVersion, datasetId, artifactRevision, provenance, talents } };
}
